import { build } from 'esbuild';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
const bundle = async (src, dst) => { await build({ entryPoints: [src], bundle: true, format: 'esm', platform: 'node', write: true, outfile: dst, logLevel: 'silent' }); return import(pathToFileURL(dst).href + '?v=' + Math.random()); };
const orig = await bundle('src/module.ts', 'out/_orig.mjs');
const cand = await bundle(process.argv[2], 'out/_cand.mjs');

let seed = 12345; const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const ri = (a, b) => a + Math.floor(rnd() * (b - a + 1));
const pick = a => a[Math.floor(rnd() * a.length)];

// ---- tokens ----
const CH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789  -_.';
const genText = () => { const n = ri(0, 40); let s = ''; while (s.length < n) { const r = rnd(); if (r < 0.2) { const k = ri(2, 5); for (let i = 0; i < k; i++) s += pick('ABCDEFGHIJKLMNOPQRSTUVWXYZ'); } else if (r < 0.3) { s += String(ri(0, 999)); } else s += CH[Math.floor(rnd() * CH.length)]; } return s.slice(0, n); };
const texts = ['', 'Id_MAX ', ' ', '---', 'HTTPRequest', 'a1b2C3', 'ABC123def', 'x.y.z', '__', 'MAXValue_9']; 
for (let i = 0; i < 60000; i++) texts.push(genText());
let bad = 0;
for (const t of texts) { const a = orig.tokens(t), b = cand.tokens(t); if (JSON.stringify(a) !== JSON.stringify(b)) { if (bad++ < 10) console.log('TOKENS DIFF', JSON.stringify(t), JSON.stringify(a), JSON.stringify(b)); } }
console.log('tokens mismatches:', bad, 'of', texts.length);

// ---- byAge ----
const names = ['jung', 'kim', 'lee', 'park', 'choi'];
const genRows = () => Array.from({ length: ri(0, 12) }, () => ({ id: ri(0, 9), name: pick(names), age: ri(18, 60) }));
let badG = 0;
for (let i = 0; i < 20000; i++) { const r = genRows(); const a = orig.byAge(r), b = cand.byAge(r); try { assert.deepStrictEqual(b, a); assert.deepStrictEqual(Object.keys(b), Object.keys(a)); } catch (e) { if (badG++ < 5) console.log('BYAGE DIFF', JSON.stringify(r)); } }
console.log('byAge mismatches:', badG);

// ---- isBlank ----
const genJson = d => { const r = rnd(); if (d > 2 || r < 0.5) { const k = ri(0, 6); if (k === 0) return null; if (k === 1) return rnd() < 0.5; if (k === 2) return ri(-5, 99); if (k === 3) return genText().slice(0, ri(0, 10)); return ri(0, 3); } if (rnd() < 0.5) return Array.from({ length: ri(0, 3) }, () => genJson(d + 1)); const o = {}; const n = ri(0, 3); for (let i = 0; i < n; i++) o[pick(['theme', 'a', 'b', 'x'])] = genJson(d + 1); return o; };
const vals = [null, true, false, 0, -5, 99, '', 'a', [], {}, [[]], [{}], { theme: [43, null, 89] }];
for (let i = 0; i < 40000; i++) vals.push(genJson(0));
let badB = 0;
for (const v of vals) { const a = orig.isBlank(v), b = cand.isBlank(v); if (a !== b) { if (badB++ < 10) console.log('ISBLANK DIFF', JSON.stringify(v), a, b); } }
console.log('isBlank mismatches:', badB, 'of', vals.length);
EOF
